export function subagentAvatarIndex(seed: string): number {
  let hash = 0;
  for (let index = 0; index < seed.length; index += 1) {
    hash = (hash * 31 + seed.charCodeAt(index)) % SUBAGENT_AVATAR_HASH_MOD;
  }
  return hash % SUBAGENT_AVATAR_PALETTE.length;
}

export function prefersDarkSubagentAvatars(): boolean {
  if (typeof document === "undefined") return false;
  const root = document.documentElement;
  const theme = root.dataset.theme ?? root.getAttribute("data-theme") ?? "";
  if (theme === "dark" || root.classList.contains("dark")) return true;
  if (theme === "light" || root.classList.contains("light")) return false;
  return window.matchMedia?.("(prefers-color-scheme: dark)").matches === true;
}

export function subagentAvatarSrc(seed: string, dark = prefersDarkSubagentAvatars()): string {
  const pair = SUBAGENT_AVATAR_PALETTE[subagentAvatarIndex(seed)] ?? SUBAGENT_AVATAR_PALETTE[0];
  return (dark ? pair?.dark : pair?.light) ?? "";
}
